SELECT 
FROM ocr_record r
LEFT JOIN user_account a ON a.id = r.account_id

    AND r.account_id = #{accountId}
    AND r.status = #{status}
    AND r.created_at >= CONCAT(#{start}, ' 00:00:00')
    AND r.created_at <= CONCAT(#{end}, ' 23:59:59')

ORDER BY r.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM ocr_record r

    AND r.account_id = #{accountId}
    AND r.status = #{status}
    AND r.created_at >= CONCAT(#{start}, ' 00:00:00')
    AND r.created_at <= CONCAT(#{end}, ' 23:59:59')
